import { parentSectorLabel } from '@sdk/sectors.sdk'
import type{ComplaintAnalytics,ComplaintReportPeriod}from'../types'
const labels:Record<ComplaintReportPeriod,string>={daily:'اليومي',weekly:'الأسبوعي',monthly:'الشهري',semiannual:'النصف سنوي',annual:'السنوي'}
const statusLabels:Record<string,string>={under_review:'بانتظار الفرز',assigned:'مسندة',in_progress:'قيد المعالجة',processed:'بانتظار التدقيق',quality_review:'قيد التدقيق',approved:'معتمدة',returned:'معادة'}
const esc=(value:unknown)=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]!))
export function complaintAnalyticsHtml(data:ComplaintAnalytics,period:ComplaintReportPeriod){
 const max=Math.max(1,...data.daily.map(v=>v.total));const sector=data.sector?parentSectorLabel(data.sector):'جميع القواطع'
 const rate=(value:number)=>data.summary.total?`${Math.round(value/data.summary.total*100)}%`:'0%'
 const cards=[['إجمالي الشكاوى',data.summary.total],['المعتمدة',data.summary.approved],['قيد العمل',data.summary.active],['بانتظار التدقيق',data.summary.review],['غير المسندة',data.summary.unassigned],['صور معالجة',data.summary.withAfter],['نسبة الاعتماد',rate(data.summary.approved)],['تغطية صور بعد',rate(data.summary.withAfter)],['المتبقي التشغيلي',Math.max(0,data.summary.total-data.summary.approved)]]
 const insights=[data.summary.unassigned>0?`توجد ${data.summary.unassigned} تذكرة غير مسندة وتحتاج توزيعاً.`:'كل التذاكر موزعة على المسؤولين.',data.summary.review>0?`توجد ${data.summary.review} تذكرة بانتظار التدقيق.`:'لا يوجد تراكم في طابور التدقيق.',data.summary.withAfter<data.summary.approved?'ينبغي تدقيق اكتمال صور المعالجة للتذاكر المعتمدة.':'تغطية صور المعالجة متوافقة مع الاعتمادات.']
 return `<!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><title>تقرير الشكاوى ${labels[period]}</title><style>@page{size:A4;margin:12mm}*{box-sizing:border-box}body{font-family:Tahoma,Arial,sans-serif;color:#172033;margin:0;background:#f6f8fb}.sheet{max-width:1100px;margin:auto;background:white;padding:28px}.hero{padding:24px;border-radius:22px;background:linear-gradient(135deg,#075985,#0f766e);color:white}.hero h1{margin:0 0 8px}.meta{opacity:.85}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:18px 0}.card{border:1px solid #dbe5ef;border-radius:15px;padding:15px;background:#fff}.card b{display:block;font-size:27px;color:#075985;margin-top:8px}.section{margin-top:22px}.section h2{font-size:17px;border-right:5px solid #0f766e;padding-right:9px}.bars{display:grid;gap:8px}.bar{display:grid;grid-template-columns:90px 1fr 45px;align-items:center;gap:8px;font-size:12px}.track{height:14px;background:#e8eef4;border-radius:999px;overflow:hidden}.fill{height:100%;background:linear-gradient(90deg,#14b8a6,#0284c7)}table{width:100%;border-collapse:collapse;font-size:12px}thead{display:table-header-group}tr{break-inside:avoid}th,td{border-bottom:1px solid #e2e8f0;padding:9px;text-align:right}th{background:#f1f5f9}.footer{margin-top:28px;border-top:1px solid #dbe5ef;padding-top:12px;color:#64748b;font-size:11px}@media print{body{background:white}.sheet{padding:0}.no-print{display:none}}@media(max-width:700px){.cards{grid-template-columns:repeat(2,1fr)}}</style></head><body><main class="sheet"><header class="hero"><h1>تقرير الشكاوى ${labels[period]}</h1><div class="meta">${sector} · من ${esc(data.from)} إلى ${esc(data.to)}</div></header><section class="cards">${cards.map(([l,v])=>`<div class="card"><span>${esc(l)}</span><b>${v}</b></div>`).join('')}</section><section class="section"><h2>حركة الشكاوى خلال الفترة</h2><div class="bars">${data.daily.filter(v=>v.total>0).map(v=>`<div class="bar"><span>${esc(v.day)}</span><div class="track"><div class="fill" style="width:${Math.max(3,v.total/max*100)}%"></div></div><b>${v.total}</b></div>`).join('')||'<p>لا توجد بيانات ضمن الفترة.</p>'}</div></section><section class="section"><h2>التفصيل اليومي</h2><table><thead><tr><th>اليوم</th><th>الإجمالي</th><th>المعتمد</th><th>قيد العمل</th><th>التدقيق</th></tr></thead><tbody>${data.daily.map(v=>`<tr><td>${esc(v.day)}</td><td>${v.total}</td><td>${v.approved}</td><td>${v.active}</td><td>${v.review}</td></tr>`).join('')}</tbody></table></section><section class="section"><h2>مؤشرات وتنبيهات تشغيلية</h2><div class="cards">${insights.map(value=>`<div class="card"><span>${esc(value)}</span></div>`).join('')}</div></section><section class="section"><h2>التوزيع حسب الحالة</h2><table><thead><tr><th>الحالة</th><th>العدد</th><th>النسبة</th></tr></thead><tbody>${data.statuses.map(v=>`<tr><td>${esc(statusLabels[v.status]??v.status)}</td><td>${v.count}</td><td>${data.summary.total?Math.round(v.count/data.summary.total*100):0}%</td></tr>`).join('')}</tbody></table></section><section class="section"><h2>القواطع</h2><table><thead><tr><th>القاطع</th><th>الإجمالي</th><th>المعتمد</th></tr></thead><tbody>${data.sectors.map(v=>`<tr><td>${parentSectorLabel(v.sector)}</td><td>${v.count}</td><td>${v.approved}</td></tr>`).join('')}</tbody></table></section><footer class="footer">تم إنشاء هذا التقرير إلكترونياً من بوابة الشكاوى · ${new Date().toLocaleString('ar-IQ-u-nu-latn',{timeZone:'Asia/Baghdad'})}</footer></main></body></html>`
}
export function downloadComplaintAnalytics(data:ComplaintAnalytics,period:ComplaintReportPeriod){const blob=new Blob([complaintAnalyticsHtml(data,period)],{type:'text/html;charset=utf-8'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=`complaints-${period}-${data.from}-${data.to}.html`;link.click();URL.revokeObjectURL(url)}
export function printComplaintAnalytics(data:ComplaintAnalytics,period:ComplaintReportPeriod){const win=window.open('','_blank');if(!win)throw new Error('PRINT_WINDOW_BLOCKED');win.document.write(complaintAnalyticsHtml(data,period));win.document.close();win.focus();window.setTimeout(()=>win.print(),250)}
